   if(phase==3){if(editorDragObject!=null && editorDragged){EditorDocument.Changed();}editorPointer=false;editorDragObject=null;return;}
   if(!editorPointer && y>=231 && y<279){if(phase==0){editorScrubTime=editorTime;}if(phase==0 || phase==1){if(y<244)EditorSeek(EditorDocument.Snap(Math.Max(0,(x-8)/464)*editorDuration,editorDivisor));else EditorSeek(EditorDocument.Snap(editorScrubTime+(x-240)/editorZoom,editorDivisor));}return;}
   if(phase==0){if(x<62 || x>350 || y<42 || y>229){Tap(x,y);return;}EditorPlay(false);editorPointer=true;editorDragged=false;editorDownX=x;editorDownY=y;var p=EditorPoint(x,y);editorOldX=p.X;editorOldY=p.Y;editorEndX=p.X;editorEndY=p.Y;editorDragObject=null;
    if(editorTool==0){double best=22*22;foreach(var obj in EditorDocument.Objects){if(Math.Abs(obj.Time-editorTime)>1200 && !(obj.Time<=editorTime && EditorDocument.EndTime(obj)>=editorTime))continue;double ox=82+obj.X*.474,oy=45+obj.Y*.474;double distance=(x-ox)*(x-ox)+(y-oy)*(y-oy);if(distance<best){best=distance;editorDragObject=obj;}}EditorDocument.SelectedId=editorDragObject==null?-1:editorDragObject.Id;if(editorDragObject!=null){editorOldX=editorDragObject.X;editorOldY=editorDragObject.Y;}return;}
   }
   if(phase==1 && editorPointer){var p=EditorPoint(x,y);editorEndX=p.X;editorEndY=p.Y;if(Math.Abs(x-editorDownX)+Math.Abs(y-editorDownY)>4){if(!editorDragged && editorDragObject!=null)EditorDocument.Before();editorDragged=true;if(editorDragObject!=null){var origin=EditorPoint(editorDownX,editorDownY);editorDragObject.Move(Math.Max(0,Math.Min(512,editorOldX+p.X-origin.X)),Math.Max(0,Math.Min(384,editorOldY+p.Y-origin.Y)));}}return;}
   if(phase==2 && editorPointer){editorPointer=false;if(editorTool==0){if(editorDragged && editorDragObject!=null)EditorDocument.Changed();editorDragObject=null;return;}ObjectKind kind=editorTool==2?ObjectKind.Slider:editorTool==3?ObjectKind.Spinner:editorTool==4?ObjectKind.Hold:ObjectKind.Circle;var p=EditorPoint(x,y);if(kind==ObjectKind.Slider && !editorDragged){p.X=Math.Min(512,editorOldX+96);p.Y=editorOldY;}EditorDocument.Add(kind,editorTime,editorOldX,editorOldY,p.X,p.Y,editorDivisor);return;}
  }
